describe('Account Locking Feature', () => {
    const adminCredentials = { username: 'admin', password: 'admin123' };
    const userCredentials = { username: 'testuser', password: 'wrongpassword' };

    beforeEach(() => {
        cy.visit('/login');
    });

    it('should lock the account after 5 failed login attempts', () => {
        for (let i = 0; i < 5; i++) {
            cy.get('input[name="username"]').type(userCredentials.username);
            cy.get('input[name="password"]').type(userCredentials.password);
            cy.get('button[type="submit"]').click();
            cy.contains('Invalid username or password').should('be.visible');
        }
        cy.get('input[name="username"]').type(userCredentials.username);
        cy.get('input[name="password"]').type(userCredentials.password);
        cy.get('button[type="submit"]').click();
        cy.contains('Your account has been locked due to too many failed login attempts').should('be.visible');
    });

    it('should allow admin to unlock the account', () => {
        cy.login(adminCredentials.username, adminCredentials.password);
        cy.visit('/admin/users');
        cy.get('input[name="search"]').type(userCredentials.username);
        cy.get('button[type="submit"]').click();
        cy.contains(userCredentials.username).parent().find('button.unlock').click();
        cy.contains('Account unlocked successfully').should('be.visible');
    });
});
